G={'A':A,'1/A':1/A,'A2':A**2,'logA':np.log(A),'sqrtA':np.sqrt(A),'expA':np.exp(-A),'expA+':np.exp(A),'A3':A**3,'1':np.ones_like(A),'A*logA':A*np.log(A),'1/A2':1/A**2}
out=[]
for gn,g in G.items():
  for hn in ['cos','sin','t','t2','sqrt','log','inv','exp','tcos']:
    if hn in ('cos','sin','tcos'):
      ws=np.linspace(0.1,4,25)
    else: ws=[0]
    best=None
    for w in ws:
      if hn=='cos': h=lambda k: np.cos(k*t)
      elif hn=='sin': h=lambda k: np.sin(k*t)
      elif hn=='t': h=lambda k: t
      elif hn=='t2': h=lambda k: t**2
      elif hn=='sqrt': h=lambda k: np.sqrt(t)
      elif hn=='log': h=lambda k: np.log(t)
      elif hn=='inv': h=lambda k: 1/t
      elif hn=='exp': h=lambda k: np.exp(-k*t)
      else: h=lambda k: t*np.cos(k*t)
      def res(q):
        return q[0]/t+q[1]*np.log(1+q[2]*t)*A**2+q[3]*h(q[4])*g-y
      try:
        r=least_squares(res,[9.7,-0.9,0.05,0.1,w if hn not in('exp',) else 0.3])
        sc=np.mean(r.fun**2)/np.var(y)
        if np.isfinite(sc) and (best is None or sc<best[0]): best=(sc,r.x.round(3))
      except Exception: pass
    if best: out.append((best[0],gn,hn,best[1]))
out.sort(key=lambda z:z[0])
